html:
{%- macro n(x) -%}{{ "%g"|format((x or 0)|round(1)) }}{%- endmacro -%}
{%- set tpl = frappe.get_doc("Report Card Template", doc.template) -%}
{%- set settings = frappe.get_doc("SchoolOS Settings") -%}
{%- set stu = frappe.db.get_value("Student", doc.student, ["student_name", "date_of_birth"], as_dict=True) -%}
{%- set guardians = frappe.get_all("Student Guardian", filters={"parent": doc.student, "parenttype": "Student"}, fields=["guardian_name", "relation"], order_by="idx asc") -%}
{%- set labels = doc.get_exam_labels() -%}
{%- set breakdown = tpl.show_criteria_breakdown -%}
{%- set is_cbse = tpl.board == "CBSE" -%}
{%- set is_mh = tpl.board == "Maharashtra State Board" -%}
{%- set school = settings.school_display_name or frappe.db.get_single_value("Education Settings", "school_college_name_abbreviation") or "" -%}
{%- set logo = settings.school_logo or frappe.db.get_single_value("Education Settings", "school_college_logo") -%}
{%- set scale = frappe.get_all("Grading Scale Interval", filters={"parent": tpl.grading_scale, "parenttype": "Grading Scale"}, fields=["grade_code", "threshold"], order_by="threshold desc") -%}
{%- set ns = namespace(exam_cols=0) -%}
{%- for label in labels -%}{%- set ns.exam_cols = ns.exam_cols + 2 + ((doc.get_criteria(label)|length) if breakdown else 0) -%}{%- endfor -%}
<style>
	.rc { font-family: Arial, Helvetica, sans-serif; font-size: 11px; color: #111; }
	.rc table { width: 100%; border-collapse: collapse; margin-bottom: 10px; }
	.rc th, .rc td { border: 1px solid #555; padding: 4px 5px; text-align: center; }
	.rc td.l, .rc th.l { text-align: left; }
	.rc .head { text-align: center; border-bottom: 2px solid #222; padding-bottom: 8px; margin-bottom: 10px; }
	.rc .head img { height: 60px; }
	.rc .school { font-size: 18px; font-weight: bold; text-transform: uppercase; }
	.rc .addr { font-size: 10px; color: #333; }
	.rc .title { font-size: 13px; font-weight: bold; margin-top: 4px; text-transform: uppercase; letter-spacing: .5px; }
	.rc table.info td { border: 0; text-align: left; padding: 2px 4px; }
	.rc .band th { background: #e9edf3; }
	.rc table.sign td { border: 0; width: 33%; padding-top: 40px; }
	.rc table.sign span { border-top: 1px solid #222; padding: 2px 20px; }
	.rc table.legend td, .rc table.legend th { font-size: 9px; padding: 2px; }
	.rc .result { font-size: 12px; font-weight: bold; }
</style>
<div class="rc">
	<div class="head">
		{% if logo %}<img src="{{ logo }}"><br>{% endif %}
		<div class="school">{{ school }}</div>
		{% if settings.school_address %}<div class="addr">{{ settings.school_address }}</div>{% endif %}
		<div class="title">
			{%- if tpl.report_title -%}{{ tpl.report_title }}
			{%- elif is_cbse -%}{{ _("Record of Academic Performance") }}
			{%- elif is_mh -%}{{ _("Progress Card") }}
			{%- else -%}{{ _("Progress Report") }}{%- endif %} · {{ doc.academic_year }}
		</div>
	</div>

	<table class="info">
		<tr>
			<td><b>{{ _("Student Name") }}:</b> {{ stu.student_name }}</td>
			<td><b>{{ _("Class / Section") }}:</b> {{ doc.student_group or doc.program or "" }}</td>
			<td><b>{{ _("Roll No.") }}:</b> {{ doc.roll_number or "" }}</td>
		</tr>
		<tr>
			<td><b>{{ _("Admission No.") }}:</b> {{ doc.student }}</td>
			<td><b>{{ _("Date of Birth") }}:</b> {{ frappe.format(stu.date_of_birth, {"fieldtype": "Date"}) if stu.date_of_birth else "" }}</td>
			<td>{% for g in guardians[:2] %}<b>{{ g.relation or _("Guardian") }}:</b> {{ g.guardian_name }}{% if not loop.last %}<br>{% endif %}{% endfor %}</td>
		</tr>
	</table>

	<table>
		<thead>
			<tr class="band"><th colspan="{{ ns.exam_cols + 4 }}" class="l">{{ _("Scholastic Areas") if is_cbse else _("Subject-wise Performance") }}</th></tr>
			<tr>
				<th rowspan="2" class="l">{{ _("Subject") }}</th>
				{%- for label in labels %}
				<th colspan="{{ 2 + ((doc.get_criteria(label)|length) if breakdown else 0) }}">{{ label }}</th>
				{%- endfor %}
				<th colspan="3">{{ _("Overall") }}</th>
			</tr>
			<tr>
				{%- for label in labels %}
					{%- if breakdown %}{% for c in doc.get_criteria(label) %}<th>{{ c }}</th>{% endfor %}{% endif %}
					<th>{{ _("Total") }}</th><th>{{ _("Grade") }}</th>
				{%- endfor %}
				<th>{{ _("Marks") }}</th><th>%</th><th>{{ _("Grade") }}</th>
			</tr>
		</thead>
		<tbody>
		{%- for s in doc.subjects %}
			<tr>
				<td class="l">{{ frappe.db.get_value("Course", s.course, "course_name") or s.course }}</td>
				{%- for label in labels %}
					{%- if breakdown %}{% for c in doc.get_criteria(label) %}{% set m = doc.get_mark(s.course, label, c) %}<td>{{ (n(m.obtained) ~ "/" ~ n(m.maximum)) if m else "–" }}</td>{% endfor %}{% endif %}
					{%- set t = doc.get_mark(s.course, label, "") %}
					<td>{{ (n(t.obtained) ~ "/" ~ n(t.maximum)) if t else "–" }}</td>
					<td>{{ t.grade if t else "" }}</td>
				{%- endfor %}
				<td>{{ n(s.total_obtained) }}/{{ n(s.total_maximum) }}</td>
				<td>{{ "%.1f"|format(s.percentage or 0) }}</td>
				<td><b>{{ s.grade }}</b></td>
			</tr>
		{%- endfor %}
		</tbody>
		<tfoot>
			<tr>
				<th class="l" colspan="{{ ns.exam_cols + 1 }}">{{ _("Grand Total") }}</th>
				<th>{{ n(doc.total_obtained) }}/{{ n(doc.total_maximum) }}</th>
				<th>{{ "%.1f"|format(doc.overall_percentage or 0) }}</th>
				<th>{{ doc.overall_grade }}</th>
			</tr>
		</tfoot>
	</table>

	{% if doc.co_scholastic %}
	<table>
		<tr class="band"><th colspan="3" class="l">{{ _("Co-Scholastic Areas") if is_cbse else _("Co-Curricular Activities & Personal Qualities") }}</th></tr>
		<tr><th class="l">{{ _("Area") }}</th><th>{{ _("Grade") }}</th><th class="l">{{ _("Remarks") }}</th></tr>
		{% for c in doc.co_scholastic %}
		<tr><td class="l">{{ c.area }}</td><td>{{ c.grade or "" }}</td><td class="l">{{ c.remarks or "" }}</td></tr>
		{% endfor %}
	</table>
	{% endif %}

	<table>
		<tr>
			<td class="l"><b>{{ _("Attendance") }}:</b> {{ doc.days_present or 0 }} / {{ doc.working_days or 0 }} {{ _("days") }} ({{ "%.1f"|format(doc.attendance_percentage or 0) }}%)</td>
			<td class="l result">{{ _("Result") }}: {{ _(doc.result) if doc.result else "" }}{% if doc.promoted_to %} · {{ _("Promoted to") }} {{ doc.promoted_to }}{% endif %}</td>
		</tr>
		<tr><td class="l" colspan="2"><b>{{ _("Class Teacher's Remarks") }}:</b> {{ doc.teacher_remarks or "" }}</td></tr>
	</table>

	<table class="sign">
		<tr>
			<td><span>{{ tpl.class_teacher_label or _("Class Teacher") }}</span></td>
			<td><span>{{ tpl.principal_label or _("Principal") }}</span></td>
			<td><span>{{ _("Parent / Guardian") }}</span></td>
		</tr>
	</table>

	{% if scale %}
	<table class="legend">
		<tr><th class="l">{{ _("Grade") }}</th>{% for g in scale %}<td><b>{{ g.grade_code }}</b></td>{% endfor %}</tr>
		<tr><th class="l">{{ _("Marks %") }}</th>{% for g in scale %}<td>{{ "%g"|format(g.threshold) }}{% if loop.first %}–100{% else %}–{{ "%g"|format(scale[loop.index0 - 1].threshold - 1) }}{% endif %}</td>{% endfor %}</tr>
	</table>
	{% endif %}
</div>
